[CmdletBinding()]
param(
  [string]$ProjectRoot = "C:\Users\techn\heather-massage-site",
  [switch]$NoBuild,
  [switch]$StartDev
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Write-Step {
  param([string]$Message)
  Write-Host ""
  Write-Host "============================================================" -ForegroundColor DarkGreen
  Write-Host $Message -ForegroundColor Green
  Write-Host "============================================================" -ForegroundColor DarkGreen
}

function Assert-ExitCode {
  param([string]$CommandName)
  if ($LASTEXITCODE -ne 0) {
    throw "$CommandName failed with exit code $LASTEXITCODE."
  }
}

function Write-Utf8NoBom {
  param(
    [Parameter(Mandatory = $true)]
    [string]$Path,
    [Parameter(Mandatory = $true)]
    [string]$Content
  )

  $Encoding = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $Encoding)
}

$ProjectRoot = [System.IO.Path]::GetFullPath($ProjectRoot)
$SitePath = Join-Path $ProjectRoot "src\lib\site.ts"
$PackagePath = Join-Path $ProjectRoot "package.json"

Write-Step "McKenzie House Massage - five-service menu update"

if (-not (Test-Path -LiteralPath $PackagePath -PathType Leaf)) {
  throw "package.json was not found in $ProjectRoot."
}

$Package = Get-Content -LiteralPath $PackagePath -Raw | ConvertFrom-Json

if ($Package.name -ne "heather-massage-site") {
  throw "Wrong project detected. Expected heather-massage-site but found $($Package.name)."
}

if (-not (Test-Path -LiteralPath $SitePath -PathType Leaf)) {
  throw "src\lib\site.ts was not found in $ProjectRoot."
}

Set-Location -LiteralPath $ProjectRoot

Write-Step "1. Creating a timestamped backup"

$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupPath = "$SitePath.backup-$Timestamp"

Copy-Item -LiteralPath $SitePath -Destination $BackupPath -Force

Write-Host "Backup created:" -ForegroundColor Cyan
Write-Host $BackupPath

Write-Step "2. Installing the complete updated site.ts"

$EncodedSite = ""
$UpdatedSite = [System.Text.Encoding]::UTF8.GetString(
  [System.Convert]::FromBase64String($EncodedSite)
)

Write-Utf8NoBom -Path $SitePath -Content $UpdatedSite

Write-Host "Installed five active services:" -ForegroundColor Cyan
Write-Host "  1. Massage"
Write-Host "  2. Relaxation Massage"
Write-Host "  3. Sensory Massage"
Write-Host "  4. Seasonal Body Renewal Ritual"
Write-Host "  5. Active Recovery Cupping"

Write-Step "3. Clearing stale Next.js output"

Remove-Item `
  -LiteralPath (Join-Path $ProjectRoot ".next") `
  -Recurse `
  -Force `
  -ErrorAction SilentlyContinue

if (-not $NoBuild) {
  Write-Step "4. Running TypeScript validation"

  $ScriptNames = @()
  if ($Package.scripts) {
    $ScriptNames = @($Package.scripts.PSObject.Properties.Name)
  }

  if ($ScriptNames -contains "typecheck") {
    & npm.cmd run typecheck
  }
  else {
    & npx.cmd tsc --noEmit
  }

  Assert-ExitCode "TypeScript validation"

  Write-Step "5. Running the production build"

  & npm.cmd run build
  Assert-ExitCode "Production build"

  Write-Host ""
  Write-Host "Service-menu update installed and validated successfully." -ForegroundColor Green
}
else {
  Write-Host ""
  Write-Host "The update was installed without validation because -NoBuild was supplied." -ForegroundColor Yellow
}

if ($StartDev) {
  Write-Step "Starting the development server"
  & npm.cmd run dev
}
else {
  Write-Host ""
  Write-Host "Start the site with:" -ForegroundColor Cyan
  Write-Host "npm run dev"
}
